events = [(2, 5), (7, 3), (11, 8), (15, 2), (23, 6), (26, 4)]
WINDOW_SIZE = 10

def window_start(timestamp, size):
    return (timestamp // size) * size

windows = {}
for timestamp, value in events:
    start = window_start(timestamp, WINDOW_SIZE)
    windows.setdefault(start, []).append(value)

for start in sorted(windows):
    values = windows[start]
    print("[" + str(start) + ", " + str(start + WINDOW_SIZE) + ") -> count=" + str(len(values)) + " sum=" + str(sum(values)))
